mapper.update:
update platform_component_operation
`status` = #{status,jdbcType=VARCHAR}, message = #{message,jdbcType=VARCHAR}, log_tail = #{logTail,jdbcType=VARCHAR}, finished_at = #{finishedAt,jdbcType=TIMESTAMP},
where id = #{id,jdbcType=BIGINT}

mapper.select:
select count(*) from platform_component_operation
where cluster_id = #{clusterId,jdbcType=VARCHAR}
  and component_code = #{componentCode,jdbcType=VARCHAR}
  and `status` in ('PENDING', 'RUNNING')
